/* h1check.c -- checks the counterexample of the paper without Lean or SAT.
 *
 * K is the 14-element lattice given by its covering pairs. The program
 *   1. builds the order of K, checks that every pair has a join and a meet, and that K is
 *      semidistributive (both laws, all triples);
 *   2. checks the D-cycle 6 D 7 D 8 D 6 of Remark 3.2 and the order-reversing bijection of Remark 5.2;
 *   3. builds L as the sublattice of K x K generated by the diagonal and (1,3), checks that it is the
 *      set of pairs x <= y <= phi(x) of Table 2, has 26 elements and is semidistributive;
 *   4. checks that the diagonal D is a maximal proper sublattice of L: for every c in C = L - D the
 *      sublattice generated by D and c is all of L;
 *   5. checks that C has minimal elements (1,3), (2,7) and maximal elements (5,10), (12,11), that
 *      (1,3) ^ (2,7) = (0,0) lies in D, and that (1,3) < (3,3) < (3,6);
 *   6. lists the distinct sublattices of K x K generated by the diagonal and one further pair, with
 *      their sizes (data/single_pair_sizes.txt).
 * Exit status 0 means every check passed. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define N 14
#define P (N * N)

static const int covers[][2] = {{0,1},{0,2},{1,3},{1,4},{2,4},{2,7},{3,5},{3,6},{4,9},{5,10},
                                {6,8},{6,9},{7,12},{8,10},{8,11},{9,12},{10,13},{11,13},{12,11}};
static const int phi[N] = {0, 6, 7, 8, 12, 10, 8, 7, 8, 11, 10, 11, 11, 13};
static const int dual[N] = {13, 11, 10, 12, 8, 7, 9, 5, 4, 6, 2, 1, 3, 0};

static int le[N][N], jn[N][N], mt[N][N];
static int fails = 0;

#define CHECK(cond, ...) do { if (!(cond)) { printf("FAIL: " __VA_ARGS__); printf("\n"); fails++; } } while (0)

static int pj(int a, int b) { return jn[a / N][b / N] * N + jn[a % N][b % N]; }
static int pm(int a, int b) { return mt[a / N][b / N] * N + mt[a % N][b % N]; }
static int ple(int a, int b) { return le[a / N][b / N] && le[a % N][b % N]; }

/* closure of S (a 0/1 array over K x K) under componentwise join and meet; returns its size */
static int closure(char *S) {
  int changed = 1;
  while (changed) {
    changed = 0;
    for (int a = 0; a < P; a++) if (S[a])
      for (int b = 0; b < P; b++) if (S[b]) {
        int j = pj(a, b), m = pm(a, b);
        if (!S[j]) { S[j] = 1; changed = 1; }
        if (!S[m]) { S[m] = 1; changed = 1; }
      }
  }
  int c = 0;
  for (int a = 0; a < P; a++) c += S[a];
  return c;
}

/* both semidistributive laws on the elements of S, with componentwise operations */
static int semidistributive(const char *S) {
  for (int a = 0; a < P; a++) if (S[a])
    for (int b = 0; b < P; b++) if (S[b])
      for (int c = 0; c < P; c++) if (S[c]) {
        if (pj(a, b) == pj(a, c) && pj(a, b) != pj(a, pm(b, c))) return 0;
        if (pm(a, b) == pm(a, c) && pm(a, b) != pm(a, pj(b, c))) return 0;
      }
  return 1;
}

int main(void) {
  /* 1. the lattice K */
  for (int i = 0; i < N; i++) le[i][i] = 1;
  for (size_t k = 0; k < sizeof covers / sizeof covers[0]; k++) le[covers[k][0]][covers[k][1]] = 1;
  for (int k = 0; k < N; k++) for (int i = 0; i < N; i++) for (int j = 0; j < N; j++)
    if (le[i][k] && le[k][j]) le[i][j] = 1;
  for (int i = 0; i < N; i++) for (int j = 0; j < N; j++)
    CHECK(!(i != j && le[i][j] && le[j][i]), "K is not antisymmetric at %d %d", i, j);
  for (int a = 0; a < N; a++) for (int b = 0; b < N; b++) {
    jn[a][b] = mt[a][b] = -1;
    for (int u = 0; u < N; u++) {
      if (le[a][u] && le[b][u]) {
        int least = 1;
        for (int w = 0; w < N; w++) if (le[a][w] && le[b][w] && !le[u][w]) least = 0;
        if (least) jn[a][b] = u;
      }
      if (le[u][a] && le[u][b]) {
        int greatest = 1;
        for (int w = 0; w < N; w++) if (le[w][a] && le[w][b] && !le[w][u]) greatest = 0;
        if (greatest) mt[a][b] = u;
      }
    }
    CHECK(jn[a][b] >= 0 && mt[a][b] >= 0, "K has no join or meet for %d %d", a, b);
  }
  if (fails) return 1;
  int sdK = 1;
  for (int a = 0; a < N; a++) for (int b = 0; b < N; b++) for (int c = 0; c < N; c++) {
    if (jn[a][b] == jn[a][c] && jn[a][b] != jn[a][mt[b][c]]) sdK = 0;
    if (mt[a][b] == mt[a][c] && mt[a][b] != mt[a][jn[b][c]]) sdK = 0;
  }
  CHECK(sdK, "K is not semidistributive");
  printf("K: lattice with %d elements, semidistributive: %s\n", N, sdK ? "yes" : "no");

  /* 2. the D-cycle (lower covers 6_* = 3, 7_* = 2, 8_* = 6) and self-duality */
  CHECK(le[6][jn[7][1]] && !le[6][jn[2][1]], "6 D 7 with witness 1");
  CHECK(le[7][jn[8][2]] && !le[7][jn[6][2]], "7 D 8 with witness 2");
  CHECK(le[8][jn[6][5]] && !le[8][jn[3][5]], "8 D 6 with witness 5");
  int dualok = 1, seen[N] = {0};
  for (int i = 0; i < N; i++) seen[dual[i]]++;
  for (int i = 0; i < N; i++) if (seen[i] != 1) dualok = 0;
  for (int i = 0; i < N; i++) for (int j = 0; j < N; j++) if (le[i][j] != le[dual[j]][dual[i]]) dualok = 0;
  CHECK(dualok, "the map of Remark 5.2 is not an order-reversing bijection");
  printf("K: D-cycle 6 D 7 D 8 D 6 checked; self-dual: %s\n", dualok ? "yes" : "no");

  /* 3. the lattice L */
  static char L[P], D[P], C[P];
  for (int x = 0; x < N; x++) D[x * N + x] = L[x * N + x] = 1;
  L[1 * N + 3] = 1;
  int nL = closure(L);
  CHECK(nL == 26, "L has %d elements, expected 26", nL);
  for (int x = 0; x < N; x++) for (int y = 0; y < N; y++)
    CHECK(L[x * N + y] == (le[x][y] && le[y][phi[x]]), "L differs from L_phi at (%d,%d)", x, y);
  int sdL = semidistributive(L);
  CHECK(sdL, "L is not semidistributive");
  printf("L: %d elements, equal to {(x,y) : x <= y <= phi(x)}, semidistributive: %s\n", nL, sdL ? "yes" : "no");

  /* 4. maximality of D */
  int nC = 0, maximal = 1;
  printf("C:");
  for (int c = 0; c < P; c++) if (L[c] && !D[c]) {
    C[c] = 1; nC++;
    printf(" (%d,%d)", c / N, c % N);
    char S[P];
    memcpy(S, D, P);
    S[c] = 1;
    if (closure(S) != nL) maximal = 0;
  }
  printf("\n");
  CHECK(nC == 12, "C has %d elements, expected 12", nC);
  CHECK(maximal, "D is not maximal");
  printf("D: maximal proper sublattice of L: %s\n", maximal ? "yes" : "no");

  /* 5. shape of C */
  int mins[P], maxs[P], nmin = 0, nmax = 0;
  for (int c = 0; c < P; c++) if (C[c]) {
    int isMin = 1, isMax = 1;
    for (int d = 0; d < P; d++) if (C[d] && d != c) {
      if (ple(d, c)) isMin = 0;
      if (ple(c, d)) isMax = 0;
    }
    if (isMin) mins[nmin++] = c;
    if (isMax) maxs[nmax++] = c;
  }
  CHECK(nmin == 2 && mins[0] == 1 * N + 3 && mins[1] == 2 * N + 7, "minimal elements of C");
  CHECK(nmax == 2 && maxs[0] == 5 * N + 10 && maxs[1] == 12 * N + 11, "maximal elements of C");
  CHECK(pm(1 * N + 3, 2 * N + 7) == 0 && D[0], "(1,3) ^ (2,7) = (0,0) in D");
  CHECK(ple(1 * N + 3, 3 * N + 3) && ple(3 * N + 3, 3 * N + 6) && L[3 * N + 3] && D[3 * N + 3] && C[3 * N + 6],
        "(1,3) < (3,3) < (3,6)");
  printf("C: minimal elements (1,3) (2,7), maximal elements (5,10) (12,11); not an interval, not convex\n");

  /* 6. sublattices generated by the diagonal and one further pair */
  static char gens[P][P];
  int ngen = 0, sizes[P + 1] = {0};
  for (int p = 0; p < P; p++) if (!D[p]) {
    char S[P];
    memcpy(S, D, P);
    S[p] = 1;
    int sz = closure(S), dup = 0;
    for (int g = 0; g < ngen && !dup; g++) if (!memcmp(gens[g], S, P)) dup = 1;
    if (!dup) { memcpy(gens[ngen++], S, P); sizes[sz]++; }
  }
  printf("single pairs: %d distinct sublattices; sizes:", ngen);
  for (int s = 0; s <= P; s++) if (sizes[s]) printf(" %dx%d", s, sizes[s]);
  printf("\n");

  if (fails) { printf("%d checks FAILED\n", fails); return 1; }
  printf("all checks passed\n");
  return 0;
}
